public class DateTimeFormatter_parseInto_TriageGen1Test {













    @Test
    public void testParseInto_PartialText_ReturnsEndPosition() {
        DateTimeFormatter formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyy")
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime();
        String text = "2023-extra";

        int newPos = formatter.parseInto(instant, text, 0);

        // It should only consume "2023" (4 chars)
        Assert.assertEquals(4, newPos);
        Assert.assertEquals(2023, instant.getYear());
    }
}
